-- Core Web Vitals de las páginas públicas de Motiq: la landing, el registro de un
-- taller y el login sin taller. No pertenecen a ningún taller, así que no caben en
-- web_vitals (tenant_id NOT NULL): hasta ahora esas mediciones se descartaban y no
-- había forma de saber, con datos reales, cuánto le cuesta el disco 3D a la entrada.
--
-- Tabla de la plataforma, sin tenant_id: no va en TABLAS_CON_TENANT.
CREATE TABLE "web_vitals_publico" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "metrica" varchar(10) NOT NULL,
  "valor" double precision NOT NULL,
  "calificacion" varchar(20),
  "ruta" varchar(200) NOT NULL,
  "movil" smallint NOT NULL DEFAULT 0,
  -- Si la portada mostró el disco en 3D, la imagen fija o nada: para comparar.
  "variante" varchar(20),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_wvp_metrica" ON "web_vitals_publico" ("metrica", "created_at");
CREATE INDEX "idx_wvp_ruta" ON "web_vitals_publico" ("ruta", "metrica");
